INSERT INTO chamadas (protocolo, identificacao_cliente, estado_ddd, numero, atendido, ramal, duracao_segundos, fila_id, fila_descricao, tabulacao_id, tabulacao_descricao, agente_login, agente_nome, campanha_id, campanha_descricao, dt_inicio, dt_fim, status, hash_registro, last_sync) VALUES
INSERT INTO registro_chamadas (log, protocolo, transcricao, revisao, id_empresa) VALUES
('call_26840925976_133.wav', 26840925976, 'kethlin retorna conforme combinado. marcos confirma que a quimvale opera no lucro real, fatura cerca de r$ 1,8 milhão por mês e tem interesse em revisar créditos de insumos químicos. kethlin propõe sexta-feira às 14h e o diretor confirma a reunião.', 'Agente (KETHLIN BARBOZA): contato realizado com Marcos Vinicius (Diretor Financeiro) da empresa Polímeros & Resinas Quimvale Ltda. Kethlin retorna conforme combinado. Marcos confirma que a Quimvale opera no Lucro Real, fatura cerca de R$ 1,8 milhão por mês e tem interesse em revisar créditos de insumos químicos. Kethlin propõe sexta-feira às 14h e o diretor confirma a reunião.', 9003),
('call_26840923416_128.wav', 26840923416, 'maria eduarda retorna para cláudia após o fechamento contábil. a cfo confirma lucro real, faturamento em torno de r$ 4,5 milhões mensais e interesse em avaliar créditos. a reunião fica confirmada para quinta-feira às 10h.', 'Agente (MARIA EDUARDA PEREIRA): contato realizado com Cláudia Nogueira (CFO) da empresa Distribuidora Cataratas de Máquinas e Peças S.A.. Maria Eduarda retorna para Cláudia após o fechamento contábil. A CFO confirma Lucro Real, faturamento em torno de R$ 4,5 milhões mensais e interesse em avaliar créditos. A reunião fica confirmada para quinta-feira às 10h.', 9009),
('call_26840922386_139.wav', 26840922386, 'emanuele apresenta a falavinha e contextualiza oportunidades para metalurgia. andré informa que a empresa está no lucro real e fatura aproximadamente r$ 3,2 milhões por mês. demonstra interesse em créditos de máquinas e confirma reunião para sexta-feira às 9h30.', 'Agente (EMANOELE SACRAMENTO BATISTA): contato realizado com André Moreira (Diretor Administrativo Financeiro) da empresa Metalúrgica Horizonte Industrial Ltda. Emanuele apresenta a Falavinha e contextualiza oportunidades para metalurgia. André informa que a empresa está no Lucro Real e fatura aproximadamente R$ 3,2 milhões por mês. Demonstra interesse em créditos de máquinas e confirma reunião para sexta-feira às 9h30.', 9011),
('call_26840922366_108.wav', 26840922366, 'thayana faz follow-up com eduardo sobre os créditos de ativo permanente. o diretor confirma interesse, porém precisa alinhar internamente a participação do contador. fica combinado retorno na terça-feira seguinte às 16h.', 'Agente (THAYANA MADALENA RAMOS): contato realizado com Eduardo Fontes (Diretor Industrial e Sócio) da empresa Indústria de Usinagem Brasfer Ltda. Thayana faz follow-up com Eduardo sobre os créditos de ativo permanente. O diretor confirma interesse, porém precisa alinhar internamente a participação do contador. Fica combinado retorno na terça-feira seguinte às 16h.', 9005),
('call_26840921696_116.wav', 26840921696, 'jheniffer aborda ricardo sobre revisão tributária para indústria madeireira. ele confirma lucro real e faturamento de aproximadamente r$ 1,3 milhão ao mês. solicita uma apresentação técnica por e-mail antes de agendar uma conversa.', 'Agente (JHENIFFER QUADROS): contato realizado com Ricardo Menezes (Diretor Financeiro) da empresa Madeireira Vale Verde S.A.. Jheniffer aborda Ricardo sobre revisão tributária para indústria madeireira. Ele confirma Lucro Real e faturamento de aproximadamente R$ 1,3 milhão ao mês. Solicita uma apresentação técnica por e-mail antes de agendar uma conversa.', 9012),
('call_26839304606_135.wav', 26839304606, 'gabrielly retorna após o envio do material institucional. danilo informa que leu os cases, confirma lucro real e faturamento de r$ 1,5 milhão mensais, e aceita reunião com o especialista na sexta-feira às 11h.', 'Agente (GABRIELLY B. GUEDES): contato realizado com Danilo Prado (Diretor de Operações e Sócio) da empresa Plásticos & Injeção Alto Iguaçu Ltda. Gabrielly retorna após o envio do material institucional. Danilo informa que leu os cases, confirma Lucro Real e faturamento de R$ 1,5 milhão mensais, e aceita reunião com o especialista na sexta-feira às 11h.', 9010),
('call_26839299556_139.wav', 26839299556, 'emanuele fala com felipe, proprietário da transportadora. ele informa que a empresa opera no lucro presumido e fatura cerca de r$ 850 mil por mês. emanuele explica os critérios da campanha e encerra sem insistência.', 'Agente (EMANOELE SACRAMENTO BATISTA): contato realizado com Felipe Rocha (Proprietário) da empresa Serviços Logísticos Serra Azul Ltda. Emanuele fala com Felipe, proprietário da transportadora. Ele informa que a empresa opera no Lucro Presumido e fatura cerca de R$ 850 mil por mês. Emanuele explica os critérios da campanha e encerra sem insistência.', 9013),
('call_26839298456_116.wav', 26839298456, 'jheniffer fala com paulo, coordenador fiscal da bela vista. ele conhece o tema e pede um resumo executivo para encaminhar à diretora tributária, mas não possui autonomia para alterar a agenda. o perfil da empresa não é reconfirmado integralmente nesta ligação.', 'Agente (JHENIFFER QUADROS): contato realizado com Paulo Vieira (Coordenador Fiscal) da empresa Laticínios & Alimentos Bela Vista S.A.. Jheniffer fala com Paulo, coordenador fiscal da Bela Vista. Ele conhece o tema e pede um resumo executivo para encaminhar à Diretora Tributária, mas não possui autonomia para alterar a agenda. O perfil da empresa não é reconfirmado integralmente nesta ligação.', 9002),
('call_26839296746_133.wav', 26839296746, 'kethlin contextualiza créditos em insumos químicos e energia. larissa confirma lucro real e faturamento médio mensal de r$ 6,2 milhões. relata que não houve revisão externa recente e aceita reunião para quinta-feira às 15h30.', 'Agente (KETHLIN BARBOZA): contato realizado com Larissa Monteiro (Diretora Financeira) da empresa Química Industrial Planalto Ltda. Kethlin contextualiza créditos em insumos químicos e energia. Larissa confirma Lucro Real e faturamento médio mensal de R$ 6,2 milhões. Relata que não houve revisão externa recente e aceita reunião para quinta-feira às 15h30.', 9014),
('call_26839296116_133.wav', 26839296116, 'kethlin realiza follow-up após a primeira reunião. carlos confirma continuidade do interesse e solicita alguns dias para organizar sped e relatórios de compras. fica combinado novo contato na quarta-feira seguinte às 9h.', 'Agente (KETHLIN BARBOZA): contato realizado com Carlos Mendes (Diretor Financeiro) da empresa Metalúrgica Alvorada Sul Ltda. Kethlin realiza follow-up após a primeira reunião. Carlos confirma continuidade do interesse e solicita alguns dias para organizar SPED e relatórios de compras. Fica combinado novo contato na quarta-feira seguinte às 9h.', 9001),
('call_26839295766_116.wav', 26839295766, 'jheniffer fala com sérgio, sócio-diretor. ele confirma lucro real, mas informa faturamento médio de aproximadamente r$ 900 mil mensais. jheniffer explica o corte mínimo de r$ 1 milhão e encerra o contato com transparência.', 'Agente (JHENIFFER QUADROS): contato realizado com Sérgio Almeida (Sócio-Diretor) da empresa Alimentos Campo Nobre S.A.. Jheniffer fala com Sérgio, sócio-diretor. Ele confirma Lucro Real, mas informa faturamento médio de aproximadamente R$ 900 mil mensais. Jheniffer explica o corte mínimo de R$ 1 milhão e encerra o contato com transparência.', 9015),
('call_26839295346_116.wav', 26839295346, 'jheniffer conversa com camila, analista fiscal. ela informa que a empresa provavelmente opera no lucro real e tem faturamento acima de r$ 1 milhão, mas não possui autonomia para confirmar os dados nem agendar. ficou de encaminhar ao gerente financeiro.', 'Agente (JHENIFFER QUADROS): contato realizado com Camila Duarte (Analista Fiscal) da empresa Embalagens Sulprint Ltda. Jheniffer conversa com Camila, analista fiscal. Ela informa que a empresa provavelmente opera no Lucro Real e tem faturamento acima de R$ 1 milhão, mas não possui autonomia para confirmar os dados nem agendar. Ficou de encaminhar ao gerente financeiro.', 9016),
('call_26839295276_135.wav', 26839295276, 'gabrielly dá sequência à conta da nova petrópolis. simone confirma que o tema de icms de exportação é prioritário e solicita uma segunda conversa com especialista. agenda confirmada para terça-feira às 11h.', 'Agente (GABRIELLY B. GUEDES): contato realizado com Simone Zimmer (Diretora Financeira) da empresa Couros & Calçados Nova Petrópolis Ltda. Gabrielly dá sequência à conta da Nova Petrópolis. Simone confirma que o tema de ICMS de exportação é prioritário e solicita uma segunda conversa com especialista. Agenda confirmada para terça-feira às 11h.', 9006),
('call_26839294576_133.wav', 26839294576, 'kethlin fala com bruno, sócio da distribuidora. ele confirma lucro real e faturamento médio de r$ 2,8 milhões por mês. está em viagem e pede retorno na sexta-feira às 10h30 para avaliar a oportunidade com calma.', 'Agente (KETHLIN BARBOZA): contato realizado com Bruno Siqueira (Diretor Comercial e Sócio) da empresa Comércio de Máquinas Centro Sul Ltda. Kethlin fala com Bruno, sócio da distribuidora. Ele confirma Lucro Real e faturamento médio de R$ 2,8 milhões por mês. Está em viagem e pede retorno na sexta-feira às 10h30 para avaliar a oportunidade com calma.', 9017),
('call_26839293016_139.wav', 26839293016, 'emanuele apresenta tese de créditos sobre energia e insumos têxteis. patrícia confirma lucro real e faturamento mensal de cerca de r$ 1,15 milhão. demonstra preocupação com custos de energia e aceita reunião para quinta às 14h30.', 'Agente (EMANOELE SACRAMENTO BATISTA): contato realizado com Patrícia Lopes (Gerente Financeira) da empresa Têxtil Aurora do Sul Ltda. Emanuele apresenta tese de créditos sobre energia e insumos têxteis. Patrícia confirma Lucro Real e faturamento mensal de cerca de R$ 1,15 milhão. Demonstra preocupação com custos de energia e aceita reunião para quinta às 14h30.', 9018),
('call_26839291686_135.wav', 26839291686, 'gabrielly fala diretamente com márcio. ele informa que a transportadora é optante do simples nacional e fatura aproximadamente r$ 480 mil por mês. a agente explica que a campanha não se aplica e encerra o contato.', 'Agente (GABRIELLY B. GUEDES): contato realizado com Márcio Reis (Proprietário) da empresa Transportes Rota Segura Ltda. Gabrielly fala diretamente com Márcio. Ele informa que a transportadora é optante do Simples Nacional e fatura aproximadamente R$ 480 mil por mês. A agente explica que a campanha não se aplica e encerra o contato.', 9019),
('call_26839283836_133.wav', 26839283836, 'kethlin faz follow-up com juliana. a diretora confirma que a empresa continua interessada no tema, mas está em auditoria externa e não quer assumir nova agenda agora. não foi definida data de retomada.', 'Agente (KETHLIN BARBOZA): contato realizado com Juliana Castelli (Diretora Financeira) da empresa Agroindustrial Serra da Esperança S.A.. Kethlin faz follow-up com Juliana. A diretora confirma que a empresa continua interessada no tema, mas está em auditoria externa e não quer assumir nova agenda agora. Não foi definida data de retomada.', 9007),
('call_26839283756_139.wav', 26839283756, 'emanuele conversa com fernanda sobre eficiência tributária no agro. a diretora confirma lucro real e faturamento mensal próximo de r$ 5 milhões. relata interesse em revisar pis/cofins de insumos e confirma reunião para sexta-feira às 15h.', 'Agente (EMANOELE SACRAMENTO BATISTA): contato realizado com Fernanda Costa (Diretora Financeira) da empresa Agroindústria Campos Altos Ltda. Emanuele conversa com Fernanda sobre eficiência tributária no agro. A diretora confirma Lucro Real e faturamento mensal próximo de R$ 5 milhões. Relata interesse em revisar PIS/Cofins de insumos e confirma reunião para sexta-feira às 15h.', 9020),
('call_26839283466_116.wav', 26839283466, 'jheniffer conversa com luciana, gerente fiscal. ela confirma lucro real e faturamento de r$ 1,4 milhão mensais, demonstra interesse, mas informa que a decisão sobre reuniões externas é do diretor financeiro. solicita material para encaminhamento.', 'Agente (JHENIFFER QUADROS): contato realizado com Luciana Prado (Gerente Fiscal) da empresa Plásticos União Fabril Ltda. Jheniffer conversa com Luciana, gerente fiscal. Ela confirma Lucro Real e faturamento de R$ 1,4 milhão mensais, demonstra interesse, mas informa que a decisão sobre reuniões externas é do Diretor Financeiro. Solicita material para encaminhamento.', 9021),
('call_26839281786_133.wav', 26839281786, 'kethlin fala com rafael, controller. ele informa que a empresa é industrial, opera no lucro real e fatura em torno de r$ 2,2 milhões mensais, mas o cfo decide sobre consultorias. pede retorno na sexta às 8h30 após conversar com ele.', 'Agente (KETHLIN BARBOZA): contato realizado com Rafael Martins (Controller) da empresa Metalúrgica Norte Catarinense Ltda. Kethlin fala com Rafael, controller. Ele informa que a empresa é industrial, opera no Lucro Real e fatura em torno de R$ 2,2 milhões mensais, mas o CFO decide sobre consultorias. Pede retorno na sexta às 8h30 após conversar com ele.', 9022);
INSERT INTO avaliacao_ia (log, data_avaliacao, modelo_ia, interlocutor, cargo, empresa_contatada, resultado, ligacao_relevante, reuniao_confirmada, data_confirmada, conversa_decisor, resultado_frase) VALUES
('call_26840925976_133.wav', '2026-10-06', 'gemini-2.5-flash', 'Marcos Vinicius', 'Diretor Financeiro', 9003, 'Perfil confirmado', 's', 's', 's', 's', 'Segundo contato com a Quimvale. Marcos confirmou os dados de perfil e aceitou reunião técnica para sexta-feira às 14h.'),
('call_26840923416_128.wav', '2026-10-06', 'gemini-2.5-flash', 'Cláudia Nogueira', 'CFO', 9009, 'Perfil confirmado', 's', 's', 's', 's', 'Follow-up após o fechamento contábil. Cláudia confirmou disponibilidade e reunião para quinta-feira às 10h.'),
('call_26840922386_139.wav', '2026-10-06', 'gemini-2.5-flash', 'André Moreira', 'Diretor Administrativo Financeiro', 9011, 'Perfil confirmado', 's', 's', 's', 's', 'Primeiro contato com a Metalúrgica Horizonte. Perfil aderente e reunião confirmada para sexta-feira às 9h30.'),
('call_26840922366_108.wav', '2026-10-06', 'gemini-2.5-flash', 'Eduardo Fontes', 'Diretor Industrial e Sócio', 9005, 'Perfil confirmado', 's', 'n', 's', 's', 'Eduardo manteve interesse, mas pediu uma semana para alinhamento interno. Retorno fixado para terça-feira às 16h.'),
('call_26840921696_116.wav', '2026-10-06', 'gemini-2.5-flash', 'Ricardo Menezes', 'Diretor Financeiro', 9012, 'Perfil confirmado', 's', 'n', 'n', 's', 'Ricardo confirmou o perfil, mas pediu material antes de abrir agenda para reunião.'),
('call_26839304606_135.wav', '2026-10-06', 'gemini-2.5-flash', 'Danilo Prado', 'Diretor de Operações e Sócio', 9010, 'Perfil confirmado', 's', 's', 's', 's', 'Após avaliar o material, Danilo confirmou interesse e reunião técnica para sexta às 11h.'),
('call_26839299556_139.wav', '2026-10-06', 'gemini-2.5-flash', 'Felipe Rocha', 'Proprietário', 9013, 'Fora do perfil desta campanha', 's', 'n', 'n', 's', 'Felipe confirmou Lucro Presumido e faturamento abaixo do mínimo. Contato encerrado de forma objetiva.'),
('call_26839298456_116.wav', '2026-10-06', 'gemini-2.5-flash', 'Paulo Vieira', 'Coordenador Fiscal', 9002, 'Perfil confirmado', 's', 'n', 'n', 'n', 'Contato com influenciador fiscal para preparação da reunião já existente. Sem nova reunião nesta ligação.'),
('call_26839296746_133.wav', '2026-10-06', 'gemini-2.5-flash', 'Larissa Monteiro', 'Diretora Financeira', 9014, 'Perfil confirmado', 's', 's', 's', 's', 'Larissa confirmou alto porte e interesse imediato. Reunião marcada para quinta às 15h30.'),
('call_26839296116_133.wav', '2026-10-06', 'gemini-2.5-flash', 'Carlos Mendes', 'Diretor Financeiro', 9001, 'Perfil confirmado', 's', 'n', 's', 's', 'Pós-reunião com Carlos. Próximo contato definido para validação documental na semana seguinte.'),
('call_26839295766_116.wav', '2026-10-06', 'gemini-2.5-flash', 'Sérgio Almeida', 'Sócio-Diretor', 9015, 'Fora do perfil desta campanha', 's', 'n', 'n', 's', 'Empresa tecnicamente no Lucro Real, mas com faturamento mensal de R$ 900 mil. Lead encerrado.'),
('call_26839295346_116.wav', '2026-10-06', 'gemini-2.5-flash', 'Camila Duarte', 'Analista Fiscal', 9016, 'Perfil pendente', 's', 'n', 'n', 'n', 'Boa conversa técnica, porém sem acesso ao decisor. Reunião foi proposta, mas ficou pendente de validação interna.'),
('call_26839295276_135.wav', '2026-10-06', 'gemini-2.5-flash', 'Simone Zimmer', 'Diretora Financeira', 9006, 'Perfil confirmado', 's', 's', 's', 's', 'Simone pediu aprofundamento técnico e confirmou segunda reunião para terça às 11h.'),
('call_26839294576_133.wav', '2026-10-06', 'gemini-2.5-flash', 'Bruno Siqueira', 'Diretor Comercial e Sócio', 9017, 'Perfil confirmado', 's', 'n', 's', 's', 'Bruno confirmou perfil e interesse, mas estava em deslocamento. Retorno marcado para sexta às 10h30.'),
('call_26839293016_139.wav', '2026-10-06', 'gemini-2.5-flash', 'Patrícia Lopes', 'Gerente Financeira', 9018, 'Perfil confirmado', 's', 's', 's', 's', 'Patrícia confirmou Lucro Real e faturamento aderente. Reunião marcada para quinta às 14h30.'),
('call_26839291686_135.wav', '2026-10-06', 'gemini-2.5-flash', 'Márcio Reis', 'Proprietário', 9019, 'Fora do perfil desta campanha', 'n', 'n', 'n', 's', 'Lead fora do perfil, encerrado rapidamente após confirmação do regime.'),
('call_26839283836_133.wav', '2026-10-06', 'gemini-2.5-flash', 'Juliana Castelli', 'Diretora Financeira', 9007, 'Perfil confirmado', 's', 'n', 'n', 's', 'Juliana mantém perfil aderente, mas pediu que o tema seja retomado somente após a auditoria anual.'),
('call_26839283756_139.wav', '2026-10-06', 'gemini-2.5-flash', 'Fernanda Costa', 'Diretora Financeira', 9020, 'Perfil confirmado', 's', 's', 's', 's', 'Fernanda confirmou porte elevado, Lucro Real e interesse. Reunião agendada para sexta às 15h.'),
('call_26839283466_116.wav', '2026-10-06', 'gemini-2.5-flash', 'Luciana Prado', 'Gerente Fiscal', 9021, 'Perfil confirmado', 's', 'n', 'n', 'n', 'Perfil técnico confirmado com gerente fiscal, mas decisão depende do Diretor Financeiro.'),
('call_26839281786_133.wav', '2026-10-06', 'gemini-2.5-flash', 'Rafael Martins', 'Controller', 9022, 'Perfil pendente', 's', 'n', 's', 'n', 'Controller confirmou parte do perfil, mas o avanço depende do CFO. Retorno marcado.');
