INSERT INTO crm (log, acao, responsavel, prazo, dados_extras, resumo) VALUES
('call_26840925976_133.wav', 'reunião confirmada', 'KETHLIN BARBOZA', '2026-10-09 14:00', 'Enviar convite Teams para Marcos e incluir pauta sobre créditos do setor químico.', 'Segundo contato com a Quimvale. Marcos confirmou os dados de perfil e aceitou reunião técnica para sexta-feira às 14h.'),
('call_26840923416_128.wav', 'reunião confirmada', 'MARIA EDUARDA PEREIRA', '2026-10-08 10:00', 'Reunião online com CFO e controller; levar exemplos de créditos em peças e máquinas.', 'Follow-up após o fechamento contábil. Cláudia confirmou disponibilidade e reunião para quinta-feira às 10h.'),
('call_26840922386_139.wav', 'reunião confirmada', 'EMANOELE SACRAMENTO BATISTA', '2026-10-09 09:30', 'Enviar convite e incluir especialista em créditos de ativo imobilizado.', 'Primeiro contato com a Metalúrgica Horizonte. Perfil aderente e reunião confirmada para sexta-feira às 9h30.'),
('call_26840922366_108.wav', 'retorno com data combinado', 'THAYANA MADALENA RAMOS', '2026-10-13 16:00', 'Retornar após reunião interna da diretoria para validar escopo do diagnóstico.', 'Eduardo manteve interesse, mas pediu uma semana para alinhamento interno. Retorno fixado para terça-feira às 16h.'),
('call_26840921696_116.wav', 'envio de material solicitado', 'JHENIFFER QUADROS', '2026-10-08 17:00', 'Enviar apresentação sobre créditos de energia e insumos; cobrar retorno em 48 horas.', 'Ricardo confirmou o perfil, mas pediu material antes de abrir agenda para reunião.'),
('call_26839304606_135.wav', 'reunião confirmada', 'GABRIELLY B. GUEDES', '2026-10-09 11:00', 'Danilo já recebeu o material. Enviar convite com especialista do setor plástico.', 'Após avaliar o material, Danilo confirmou interesse e reunião técnica para sexta às 11h.'),
('call_26839299556_139.wav', 'sem interesse explícito', 'EMANOELE SACRAMENTO BATISTA', 'Não se aplica', 'Lead encerrado por regime e faturamento incompatíveis.', 'Felipe confirmou Lucro Presumido e faturamento abaixo do mínimo. Contato encerrado de forma objetiva.'),
('call_26839298456_116.wav', 'envio de material solicitado', 'JHENIFFER QUADROS', '2026-10-08 12:00', 'Enviar resumo técnico para Paulo encaminhar à Diretora Tributária.', 'Contato com influenciador fiscal para preparação da reunião já existente. Sem nova reunião nesta ligação.'),
('call_26839296746_133.wav', 'reunião confirmada', 'KETHLIN BARBOZA', '2026-10-08 15:30', 'Convidar especialista tributário para indústria química.', 'Larissa confirmou alto porte e interesse imediato. Reunião marcada para quinta às 15h30.'),
('call_26839296116_133.wav', 'retorno com data combinado', 'KETHLIN BARBOZA', '2026-10-14 09:00', 'Cliente pediu prazo para reunir SPED e relatórios de compras antes do próximo contato.', 'Pós-reunião com Carlos. Próximo contato definido para validação documental na semana seguinte.'),
('call_26839295766_116.wav', 'sem interesse explícito', 'JHENIFFER QUADROS', 'Não se aplica', 'Lucro Real, porém faturamento abaixo do mínimo de campanha.', 'Empresa tecnicamente no Lucro Real, mas com faturamento mensal de R$ 900 mil. Lead encerrado.'),
('call_26839295346_116.wav', 'reunião proposta sem aceite', 'JHENIFFER QUADROS', '2026-10-09 16:30', 'Camila encaminhará o contato ao gerente financeiro. Retomar para tentar falar com decisor.', 'Boa conversa técnica, porém sem acesso ao decisor. Reunião foi proposta, mas ficou pendente de validação interna.'),
('call_26839295276_135.wav', 'reunião confirmada', 'GABRIELLY B. GUEDES', '2026-10-13 11:00', 'Segunda reunião técnica focada em saldos credores de ICMS de exportação.', 'Simone pediu aprofundamento técnico e confirmou segunda reunião para terça às 11h.'),
('call_26839294576_133.wav', 'retorno com data combinado', 'KETHLIN BARBOZA', '2026-10-09 10:30', 'Retornar após viagem do sócio; oportunidade em créditos sobre máquinas e peças.', 'Bruno confirmou perfil e interesse, mas estava em deslocamento. Retorno marcado para sexta às 10h30.'),
('call_26839293016_139.wav', 'reunião confirmada', 'EMANOELE SACRAMENTO BATISTA', '2026-10-08 14:30', 'Convidar consultor com experiência no setor têxtil.', 'Patrícia confirmou Lucro Real e faturamento aderente. Reunião marcada para quinta às 14h30.'),
('call_26839291686_135.wav', 'sem interesse explícito', 'GABRIELLY B. GUEDES', 'Não se aplica', 'Contato curto; empresa no Simples Nacional e baixo faturamento.', 'Lead fora do perfil, encerrado rapidamente após confirmação do regime.'),
('call_26839283836_133.wav', 'sem próximo passo definido', 'KETHLIN BARBOZA', 'Não se aplica', 'Cliente está concluindo auditoria externa e pediu pausa temporária nos contatos.', 'Juliana mantém perfil aderente, mas pediu que o tema seja retomado somente após a auditoria anual.'),
('call_26839283756_139.wav', 'reunião confirmada', 'EMANOELE SACRAMENTO BATISTA', '2026-10-09 15:00', 'Apresentar créditos de PIS/Cofins e insumos agroindustriais.', 'Fernanda confirmou porte elevado, Lucro Real e interesse. Reunião agendada para sexta às 15h.'),
('call_26839283466_116.wav', 'envio de material solicitado', 'JHENIFFER QUADROS', '2026-10-08 16:00', 'Luciana encaminhará apresentação ao Diretor Financeiro.', 'Perfil técnico confirmado com gerente fiscal, mas decisão depende do Diretor Financeiro.'),
('call_26839281786_133.wav', 'retorno com data combinado', 'KETHLIN BARBOZA', '2026-10-09 08:30', 'Rafael vai alinhar com o CFO e pediu retorno na sexta às 8h30.', 'Controller confirmou parte do perfil, mas o avanço depende do CFO. Retorno marcado.');
